   403  /* expand a single {abstract ...data... } */
   404  static char *theme_format_expand_abstract(THEME_REC *theme,
   405                                            const char **formatp,
   406                                            theme_rm_col *last_fg,
   407                                            theme_rm_col *last_bg,
   408                                            int flags)
   409  {
   410          GString *str;
   411          const char *p, *format;
   412          char *abstract, *data, *ret;
   413          theme_rm_col default_fg, default_bg;
   414          int len;
   415
   416          format = *formatp;
   417          default_fg = *last_fg;
   418          default_bg = *last_bg;
   419
   420          /* get abstract name first */
   421          p = format;
   422          while (*p != '\0' && *p != ' ' &&
   423                 *p != '{' && *p != '}') p++;
   424          if (*p == '\0' || p == format)
   425                  return NULL; /* error */
   426
   427          len = (int) (p-format);
   428          abstract = g_strndup(format, len);
   429
   430          /* skip the following space, if there's any more spaces they're
   431             treated as arguments */
   432          if (*p == ' ') {
   433                  len++;
   434                  if ((flags & EXPAND_FLAG_IGNORE_EMPTY) && data_is_empty(&p)) {
   435                          *formatp = p;
   436                          g_free(abstract);
   437                          return NULL;
   438                  }
   439          }
   440          *formatp = format+len;
   441
   442          /* get the abstract data */
   443          data = g_hash_table_lookup(theme->abstracts, abstract);
   444          g_free(abstract);
   445          if (data == NULL) {
   446                  /* unknown abstract, just display the data */
   447                  data = "$0-";
   448          }
   449          abstract = g_strdup(data);
   450
   451          /* we'll need to get the data part. it may contain
   452             more abstracts, they are _NOT_ expanded. */
   453          data = theme_format_expand_get(theme, formatp);
   454          len = strlen(data);
   455
   456          if (len > 1 && i_isdigit(data[len-1]) && data[len-2] == '$') {
   457                  /* ends with $<digit> .. this breaks things if next
   458                     character is digit or '-' */
   459                  char digit, *tmp;
   460
   461                  tmp = data;
   462                  digit = tmp[len-1];
   463                  tmp[len-1] = '\0';
   464
   465                  data = g_strdup_printf("%s{%c}", tmp, digit);
   466                  g_free(tmp);
   467          }
   468
   469          ret = parse_special_string(abstract, NULL, NULL, data, NULL,
   470                                     PARSE_FLAG_ONLY_ARGS);
   471          g_free(abstract);
   472          g_free(data);
   473          str = g_string_new(NULL);
   474          p = ret;
   475          while (*p != '\0') {
   476                  if (*p == '\\') {
   477                          int chr;
   478                          p++;
   479                          chr = expand_escape(&p);
   480                          g_string_append_c(str, chr != -1 ? chr : *p);
   481                  } else
   482                          g_string_append_c(str, *p);
   483                  p++;
   484          }
   485          g_free(ret);
   486          abstract = str->str;
   487          g_string_free(str, FALSE);
   488
   489          /* abstract may itself contain abstracts or replaces */
   490          p = abstract;
   491          ret = theme_format_expand_data(theme, &p, default_fg, default_bg,
   492                                         last_fg, last_bg,
   493                                         flags | EXPAND_FLAG_LASTCOLOR_ARG);
   494          g_free(abstract);
   495          return ret;
   496  }
