   498  /* expand the data part in {abstract data} */
   499  char *theme_format_expand_data(THEME_REC *theme, const char **format,
   500                                 theme_rm_col default_fg, theme_rm_col default_bg,
   501                                 theme_rm_col *save_last_fg, theme_rm_col *save_last_bg,
   502                                 int flags)
   503  {
   504          GString *str;
   505          char *ret, *abstract;
   506          theme_rm_col last_fg, last_bg;
   507          int recurse_flags;
   508
   509          last_fg = default_fg;
   510          last_bg = default_bg;
   511          recurse_flags = flags & EXPAND_FLAG_RECURSIVE_MASK;
   512
   513          str = g_string_new(NULL);
   514          while (**format != '\0') {
   515                  if ((flags & EXPAND_FLAG_ROOT) == 0 && **format == '}') {
   516                          /* ignore } if we're expanding original string */
   517                          (*format)++;
   518                          break;
   519                  }
   520
   521                  if (**format != '{') {
   522                          if ((flags & EXPAND_FLAG_LASTCOLOR_ARG) &&
   523                              **format == '$' && (*format)[1] == '0') {
   524                                  /* save the color before $0 ..
   525                                     this is for the %n replacing */
   526                                  if (save_last_fg != NULL) {
   527                                          *save_last_fg = last_fg;
   528                                          save_last_fg = NULL;
   529                                  }
   530                                  if (save_last_bg != NULL) {
   531                                          *save_last_bg = last_bg;
   532                                          save_last_bg = NULL;
   533                                  }
   534                          }
   535
   536                          theme_format_append_next(theme, str, format,
   537                                                   default_fg, default_bg,
   538                                                   &last_fg, &last_bg,
   539                                                   recurse_flags);
   540                          continue;
   541                  }
   542
   543                  (*format)++;
   544                  if (**format == '\0' || **format == '}')
   545                          break; /* error */
   546
   547                  /* get a single {...} */
   548                  abstract = theme_format_expand_abstract(theme, format,
   549                                                          &last_fg, &last_bg,
   550                                                          recurse_flags);
   551                  if (abstract != NULL) {
   552                          g_string_append(str, abstract);
   553                          g_free(abstract);
   554                  }
   555          }
   556
   557                  /* save the last color */
   558                  if (save_last_fg != NULL)
   559                          *save_last_fg = last_fg;
   560                  if (save_last_bg != NULL)
   561                          *save_last_bg = last_bg;
   562
   563          ret = str->str;
   564          g_string_free(str, FALSE);
   565          return ret;
   566  }
